# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# MAIN INFRASTRUCTURE MODULE (HA + AUTO SCALING + CONTAINERS)
# ============================================================

# Dynamic lookup for official Canonical Ubuntu 22.04 LTS AMI (HVM SSD)
data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# Dynamic secure credentials generation (zero hardcoded secrets)
resource "random_password" "db_master_password" {
  length  = 24
  special = false
}

locals {
  effective_db_password = var.db_password != null && var.db_password != "" ? var.db_password : random_password.db_master_password.result
}

# Network & Multi-AZ Isolation Boundaries
resource "aws_vpc" "target_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "cloudmove-target-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.target_vpc.id
  tags = {
    Name = "cloudmove-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.aws_region}a"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet-a"
  }
}

resource "aws_subnet" "public_subnet_b" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = "${var.aws_region}b"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet-b"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.target_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = {
    Name = "cloudmove-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_subnet_b.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "cloudmove-private-subnet-a"
  }
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "cloudmove-private-subnet-b"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "cloudmove-app-sg"
  description = "Security group for migrated containerized application workloads"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    description = "SSH administration access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 80"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 443"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 5432"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 8080"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-app-sg"
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "cloudmove-alb-sg"
  description = "Security group for High Availability Application Load Balancer"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    description = "Public HTTP ingress"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Public HTTPS ingress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-alb-sg"
  }
}

# High Availability Application Load Balancer (Multi-AZ)
resource "aws_lb" "app_alb" {
  name               = "cloudmove-app-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_subnet.id, aws_subnet.public_subnet_b.id]
  tags = {
    Name        = "cloudmove-app-alb"
    Environment = var.environment
    ManagedBy   = "CloudMove"
  }
}

resource "aws_lb_target_group" "app_tg" {
  name     = "cloudmove-app-tg"
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.target_vpc.id
  health_check {
    enabled             = true
    path                = "/v1"
    port                = "traffic-port"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
    matcher             = "200-399"
  }
  tags = {
    Name      = "cloudmove-app-tg"
    ManagedBy = "CloudMove"
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.app_alb.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }
}

resource "aws_security_group" "data_sg" {
  name        = "cloudmove-data-sg"
  description = "Security group for migrated data services"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }
  ingress {
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-data-sg"
  }
}

resource "aws_db_subnet_group" "db_subnets" {
  name       = "cloudmove-db-subnets"
  subnet_ids = [aws_subnet.private_subnet_a.id, aws_subnet.private_subnet_b.id]
  tags = {
    Name = "cloudmove-db-subnets"
  }
}

# Migrated Resource: app-runtime-host (compute-app-host)
resource "aws_launch_template" "compute_app_host_lt" {
  name_prefix            = "app-runtime-host-lt-"
  image_id               = var.ami_id != "" ? var.ami_id : data.aws_ami.ubuntu.id
  instance_type          = var.instance_type
  vpc_security_group_ids = [aws_security_group.app_sg.id]
  user_data              = filebase64("${path.module}/user_data.sh")
  tag_specifications {
    resource_type = "instance"
    tags = {
      Name      = "app-runtime-host-asg-node"
      CMIR_ID   = "compute-app-host"
      ManagedBy = "CloudMove"
    }
  }
}

resource "aws_autoscaling_group" "compute_app_host_asg" {
  name                      = "app-runtime-host-asg"
  min_size                  = var.asg_min_size
  max_size                  = var.asg_max_size
  desired_capacity          = var.asg_desired_capacity
  vpc_zone_identifier       = [aws_subnet.public_subnet.id, aws_subnet.public_subnet_b.id]
  target_group_arns         = [aws_lb_target_group.app_tg.arn]
  health_check_type         = "ELB"
  health_check_grace_period = 300
  launch_template {
    id      = aws_launch_template.compute_app_host_lt.id
    version = "$Latest"
  }
  tag {
    key                 = "Name"
    value               = "app-runtime-host-ha-container-host"
    propagate_at_launch = true
  }
}

resource "aws_instance" "compute_app_host" {
  ami                         = var.ami_id != "" ? var.ami_id : data.aws_ami.ubuntu.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids      = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  user_data                   = file("${path.module}/user_data.sh")
  user_data_replace_on_change = true
  root_block_device {
    volume_size           = 30
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }
  tags = {
    Name      = "app-runtime-host"
    CMIR_Type = "virtual_machine"
    CMIR_ID   = "compute-app-host"
    ManagedBy = "CloudMove"
  }
}

# Application Workload: app (app-app) — deployed as containerized service on host compute-app-host
# Container Component: app-app-host (compute-app-app, runtime=python:3.11) — orchestrated via Docker Compose on primary host (compute-app-host)
# Application Workload: app-app (app-app-app) — deployed as containerized service on host compute-app-app
# Container Component: app-postgres-host (compute-app-postgres, runtime=python:3.11) — orchestrated via Docker Compose on primary host (compute-app-host)
# Application Workload: app-postgres (app-app-postgres) — deployed as containerized service on host compute-app-postgres
# Container Component: app-redis-host (compute-app-redis, runtime=python:3.11) — orchestrated via Docker Compose on primary host (compute-app-host)
# Application Workload: app-redis (app-app-redis) — deployed as containerized service on host compute-app-redis
# Migrated Network Port Rule: tcp-8080 (port-app-8080) -> aws_security_group.app_sg
# Migrated Resource: app-workload-identity (identity-app-sa)
resource "aws_iam_role" "identity_app_sa" {
  name = "app-workload-identity"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name      = "app-workload-identity"
    CMIR_ID   = "identity-app-sa"
    ManagedBy = "CloudMove"
  }
}

resource "aws_iam_instance_profile" "identity_app_sa_profile" {
  name = "app-workload-identity-profile"
  role = aws_iam_role.identity_app_sa.name
}

# Migrated Resource: app-postgresql (dep-app-postgresql)
resource "aws_db_instance" "dep_app_postgresql" {
  identifier             = "app-postgresql"
  engine                 = "postgres"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  multi_az               = false
  storage_encrypted      = true
  username               = "cloudmove_admin"
  password               = local.effective_db_password
  publicly_accessible    = false
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.db_subnets.name
  vpc_security_group_ids = [aws_security_group.data_sg.id]
  tags = {
    Name      = "app-postgresql"
    CMIR_ID   = "dep-app-postgresql"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: app-redis (dep-app-redis)
resource "aws_elasticache_cluster" "dep_app_redis" {
  cluster_id           = "app-redis"
  engine               = "redis"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis7"
  port                 = 6379
  security_group_ids   = [aws_security_group.data_sg.id]
  tags = {
    Name      = "app-redis"
    CMIR_ID   = "dep-app-redis"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: app-invoices-bucket (dep-app-object-storage)
resource "aws_s3_bucket" "dep_app_object_storage" {
  bucket = "cloudmove-app-invoices-bucket"
  tags = {
    Name      = "app-invoices-bucket"
    CMIR_ID   = "dep-app-object-storage"
    ManagedBy = "CloudMove"
  }
}

# External BaaS Preserved: external-endpoint-external-api-url (dep-app-ext-external-api-url, engine=https) — connected via environment variables without provisioning redundant RDS

