# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# MAIN INFRASTRUCTURE MODULE (HA + AUTO SCALING + CONTAINERS)
# ============================================================

# Dynamic lookup for official Canonical Ubuntu 22.04 LTS AMI (HVM SSD)
data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# Network & Multi-AZ Isolation Boundaries
resource "aws_vpc" "target_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "cloudmove-target-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.target_vpc.id
  tags = {
    Name = "cloudmove-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.aws_region}a"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet-a"
  }
}

resource "aws_subnet" "public_subnet_b" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = "${var.aws_region}b"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet-b"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.target_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = {
    Name = "cloudmove-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_subnet_b.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "cloudmove-private-subnet-a"
  }
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "cloudmove-private-subnet-b"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "cloudmove-app-sg"
  description = "Security group for migrated containerized application workloads"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    description = "SSH administration access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 80"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Application TCP port 443"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-app-sg"
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "cloudmove-alb-sg"
  description = "Security group for High Availability Application Load Balancer"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    description = "Public HTTP ingress"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Public HTTPS ingress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-alb-sg"
  }
}

# High Availability Application Load Balancer (Multi-AZ)
resource "aws_lb" "app_alb" {
  name               = "cloudmove-app-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_subnet.id, aws_subnet.public_subnet_b.id]
  tags = {
    Name        = "cloudmove-app-alb"
    Environment = var.environment
    ManagedBy   = "CloudMove"
  }
}

resource "aws_lb_target_group" "app_tg" {
  name     = "cloudmove-app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.target_vpc.id
  health_check {
    enabled             = true
    path                = "/health"
    port                = "traffic-port"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
    matcher             = "200-399"
  }
  tags = {
    Name      = "cloudmove-app-tg"
    ManagedBy = "CloudMove"
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.app_alb.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }
}

# Migrated Resource: rabbitmq-kali-live-os (img-live-rabbitmq-kali)
resource "aws_ebs_snapshot_import" "img_live_rabbitmq_kali_import" {
  disk_container {
    description = "Imported disk image for rabbitmq-kali-live-os"
    format      = "RAW"
    user_bucket {
      s3_bucket = "cloudmove-vm-import-staging"
      s3_key    = "images/rabbitmq-kali-live-os.vmdk"
    }
  }
  role_name = "vmimport"
  tags = {
    Name      = "rabbitmq-kali-live-os-snapshot"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

resource "aws_ami" "img_live_rabbitmq_kali" {
  name                = "rabbitmq-kali-live-os-ami"
  virtualization_type = "hvm"
  architecture        = "x86_64"
  boot_mode           = "uefi"
  root_device_name    = "/dev/sda1"
  ena_support         = true
  ebs_block_device {
    device_name = "/dev/sda1"
    snapshot_id = aws_ebs_snapshot_import.img_live_rabbitmq_kali_import.id
    volume_size = 50
    volume_type = "gp3"
  }
  tags = {
    Name      = "rabbitmq-kali-live-os-ami"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: rabbitmq-kali-live-os-vm (vm-rabbitmq-kali-live-os)
resource "aws_launch_template" "vm_rabbitmq_kali_live_os_lt" {
  name_prefix            = "rabbitmq-kali-live-os-vm-lt-"
  image_id               = var.ami_id != "" ? var.ami_id : aws_ami.img_live_rabbitmq_kali.id
  instance_type          = var.instance_type
  vpc_security_group_ids = [aws_security_group.app_sg.id]
  user_data              = filebase64("${path.module}/user_data.sh")
  tag_specifications {
    resource_type = "instance"
    tags = {
      Name      = "rabbitmq-kali-live-os-vm-asg-node"
      CMIR_ID   = "vm-rabbitmq-kali-live-os"
      ManagedBy = "CloudMove"
    }
  }
}

resource "aws_autoscaling_group" "vm_rabbitmq_kali_live_os_asg" {
  name                      = "rabbitmq-kali-live-os-vm-asg"
  min_size                  = var.asg_min_size
  max_size                  = var.asg_max_size
  desired_capacity          = var.asg_desired_capacity
  vpc_zone_identifier       = [aws_subnet.public_subnet.id, aws_subnet.public_subnet_b.id]
  target_group_arns         = [aws_lb_target_group.app_tg.arn]
  health_check_type         = "ELB"
  health_check_grace_period = 300
  launch_template {
    id      = aws_launch_template.vm_rabbitmq_kali_live_os_lt.id
    version = "$Latest"
  }
  tag {
    key                 = "Name"
    value               = "rabbitmq-kali-live-os-vm-ha-container-host"
    propagate_at_launch = true
  }
}

resource "aws_instance" "vm_rabbitmq_kali_live_os" {
  ami                         = var.ami_id != "" ? var.ami_id : aws_ami.img_live_rabbitmq_kali.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids      = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  user_data                   = file("${path.module}/user_data.sh")
  user_data_replace_on_change = true
  root_block_device {
    volume_size           = 30
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }
  tags = {
    Name      = "rabbitmq-kali-live-os-vm"
    CMIR_Type = "virtual_machine"
    CMIR_ID   = "vm-rabbitmq-kali-live-os"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: rabbitmq-kali-live-os-disk-1 (disk-rabbitmq-kali-live-os-1)
resource "aws_ebs_volume" "disk_rabbitmq_kali_live_os_1" {
  availability_zone = "${var.aws_region}a"
  size              = 50
  type              = "gp3"
  encrypted         = true
  tags = {
    Name      = "rabbitmq-kali-live-os-disk-1"
    CMIR_ID   = "disk-rabbitmq-kali-live-os-1"
    ManagedBy = "CloudMove"
  }
}

